export const openDraftPr = async (scope: RunScope, title: string, body: string, requester: string) => {
  const octokit = new Octokit({ auth: await mintToken(scope) });
  const [owner = "", repo = ""] = scope.repo.split("/");
  const { data: pr } = await octokit.rest.pulls.create({
    owner, repo, base: "main",
    head: scope.branch,
    title,
    body: withRequestedBy(body, requester),
    draft: true,
  });
  await audit(scope, "pr.create", { number: pr.number });
  return { number: pr.number, nodeId: pr.node_id };
};

const WAITS_FOR_PEOPLE = new Set(["independent-approval / check"]);
const HANDLED = new Set(["fixed", "answered", "with_a_person"]);

export async function readyGate(pr: number, ev: GateEvidence): Promise<GateResult> {
  const checks = await gh<Check[]>(["pr", "checks", String(pr), "--required", "--json", "name,bucket"]);
  const blockers = checks
    .filter((c) => !WAITS_FOR_PEOPLE.has(c.name))
    .filter((c) => c.bucket !== "pass" && c.bucket !== "skipping")
    .map((c) => `CI: ${c.name} is ${c.bucket}`);
  blockers.push(...ev.qa_results.filter((q) => !q.passed).map((q) => `QA check ${q.id} failed`));
  const open = ev.findings.filter((f) => f.severity === "important" && !HANDLED.has(f.state));
  blockers.push(...open.map((f) => `open finding ${f.path}:${f.line}`));
  if (blockers.length) return { ready: false, blockers };
  await markReady(pr);
  await gh(["pr", "edit", String(pr), "--add-reviewer", ev.reviewer_team]);
  return { ready: true, blockers: [] };
}

